assert("Pid");
assert("VmHWM");
assert("VmRSS");
assert("VmData");
assert("VmSwap");
assert("VmSize");
assert("VmPeak");
assert("VmStk");

assert(null, "default");
assert("", "default");
assert("other", "default");
System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(string value)
    {
        return value switch
        {
            "Pid" => "Pid",
            "VmHWM" => "VmHWM",
            "VmRSS" => "VmRSS",
            "VmData" => "VmData",
            "VmSwap" => "VmSwap",
            "VmSize" => "VmSize",
            "VmPeak" => "VmPeak",
            "VmStk" => "VmStk",
            _ => "default"
        };
    }
}
